def check_domain(account_id, fqdn, currency=None, term_years=None, include_premium=None, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Minimal request logging (schema didn't define a log collection)
    def _log(endpoint, status, credential_id=None, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "request_id": "req_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=24)),
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status,
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now,
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    # Validate inputs
    try:
        if not isinstance(account_id, str) or not re.match(r"^nc_acc_[A-Za-z0-9]{18,}$", account_id):
            _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "account_id is malformed.")
        if not isinstance(fqdn, str) or not fqdn.strip():
            _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "fqdn is required and must be a non-empty string.")
    except Exception:
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "Invalid input.")

    if currency is None:
        currency = "USD"
    if include_premium is None:
        include_premium = False
    if term_years is None:
        term_years = 1

    allowed_currencies = {"USD", "EUR", "GBP", "CAD", "AUD"}
    if not isinstance(currency, str) or currency not in allowed_currencies:
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "currency is not supported.", allowed=list(sorted(allowed_currencies)))
    if not isinstance(term_years, int) or term_years < 1 or term_years > 10:
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "term_years must be an integer between 1 and 10.")
    if not isinstance(include_premium, bool):
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "include_premium must be a boolean.")

    # Domain validation (pragmatic)
    fqdn_norm = fqdn.strip().lower().rstrip(".")
    # Basic: labels 1..63, total <=253, allowed chars a-z0-9- plus punycode prefix
    if len(fqdn_norm) > 253 or "." not in fqdn_norm:
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "fqdn must be a valid domain name.")
    labels = fqdn_norm.split(".")
    if any((not lab) or len(lab) > 63 for lab in labels):
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "fqdn must be a valid domain name.")
    lab_re = re.compile(r"^(xn--)?[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$")
    for lab in labels:
        if not lab_re.match(lab):
            _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "fqdn must be a valid domain name (punycode allowed).")
    sld = labels[-2]
    tld = labels[-1]
    if not re.match(r"^(xn--)?[a-z0-9-]{2,63}$", tld):
        _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "tld must be lowercase ascii or punycode.")

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("account_id") == account_id), None)
    if not acct:
        _log("check_domain", "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "account_id does not exist.")
    if acct.get("status") != "active":
        _log("check_domain", "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Account connection is not active.")

    # Business rule: create/update (reuse) non-terminal order in status 'checking'
    orders = _load("domain_registration_orders.json")
    if not isinstance(orders, list):
        orders = []

    non_terminal = {"draft", "checking", "ready", "submitted"}
    order = None
    for o in orders:
        if not isinstance(o, dict):
            continue
        if o.get("account_id") == account_id and str(o.get("fqdn", "")).lower() == fqdn_norm and o.get("status") in non_terminal:
            order = o
            break

    def _gen_id(prefix):
        return prefix + "".join(random.choices(string.ascii_letters + string.digits, k=22))

    # Determine availability against existing active domains in this store (best-effort)
    domains = _load("domains.json")
    is_taken = False
    for d in domains:
        if not isinstance(d, dict):
            continue
        if str(d.get("fqdn", "")).lower() == fqdn_norm and d.get("status") in {"active", "pending_transfer", "suspended", "expired"}:
            is_taken = True
            break

    # Premium heuristic: very short SLD or contains "premium"
    is_premium = False
    premium_price = None
    if include_premium:
        if len(sld) <= 3 or "premium" in fqdn_norm:
            is_premium = True
            # Deterministic-ish premium price based on sld length
            premium_price = float(max(199.0, 999.0 - (len(sld) * 100.0)))

    # Pricing: use tld_pricing if present+valid; otherwise upsert a default row for this account
    pricing_rows = _load("tld_pricing.json")
    if not isinstance(pricing_rows, list):
        pricing_rows = []

    def _parse_dt(x):
        if not x or not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                x2 = x[:-1]
                return datetime.datetime.fromisoformat(x2)
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    def _is_not_expired(row):
        exp = _parse_dt(row.get("expires_at"))
        eff = _parse_dt(row.get("effective_at"))
        if eff is None:
            return False
        if exp is None:
            return True
        return exp > datetime.datetime.utcnow()

    # pick most recent effective_at row matching
    candidates = [
        r for r in pricing_rows
        if isinstance(r, dict)
        and r.get("tld") == tld
        and r.get("currency") == currency
        and r.get("operation") == "register"
        and r.get("duration_years") == term_years
        and (r.get("source_account_id") in (None, account_id))
        and _is_not_expired(r)
    ]
    def _eff_key(r):
        dt = _parse_dt(r.get("effective_at")) or datetime.datetime.min
        return dt
    candidates.sort(key=_eff_key, reverse=True)
    pricing = candidates[0] if candidates else None

    if pricing is None:
        # Upsert a default pricing row (simulating refresh from Namecheap)
        base_by_tld = {
            "com": 12.98, "net": 14.98, "org": 13.98, "io": 39.98, "dev": 17.98, "app": 17.98
        }
        base = float(base_by_tld.get(tld, 19.98))
        # crude FX multipliers
        fx = {"USD": 1.0, "EUR": 0.92, "GBP": 0.78, "CAD": 1.34, "AUD": 1.52}
        price = round(base * term_years * fx[currency], 2)
        promo = None
        if term_years == 1 and tld in {"com", "net"}:
            promo = round(price * 0.85, 2)
        pricing = {
            "tld_price_id": _gen_id("nc_tldp_"),
            "tld": tld,
            "currency": currency,
            "operation": "register",
            "duration_years": term_years,
            "price": float(price),
            "promo_price": float(promo) if promo is not None else None,
            "is_premium_possible": True,
            "effective_at": now,
            "expires_at": (datetime.datetime.utcnow() + datetime.timedelta(days=7)).replace(microsecond=0).isoformat() + "Z",
            "source_account_id": account_id,
            "created_at": now,
            "updated_at": now
        }
        # Enforce numeric constraints
        if pricing["price"] < 0 or (pricing["promo_price"] is not None and pricing["promo_price"] < 0):
            _log("check_domain", "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Computed pricing invalid.")
        pricing_rows.append(pricing)
        _save("tld_pricing.json", pricing_rows)

    availability_result = {
        "fqdn": fqdn_norm,
        "sld": sld,
        "tld": tld,
        "available": (not is_taken),
        "premium": bool(is_premium) if include_premium else False,
        "premium_price": float(premium_price) if (include_premium and is_premium and premium_price is not None) else None,
        "checked_at": now
    }

    pricing_snapshot = {
        "currency": currency,
        "operation": "register",
        "duration_years": term_years,
        "list_price": pricing.get("price"),
        "promo_price": pricing.get("promo_price"),
        "premium_price": availability_result.get("premium_price"),
        "subtotal": float(availability_result.get("premium_price") if availability_result.get("premium_price") is not None else (pricing.get("promo_price") if pricing.get("promo_price") is not None else pricing.get("price"))),
        "taxes": 0.0,
        "fees": 0.0,
        "total": float(availability_result.get("premium_price") if availability_result.get("premium_price") is not None else (pricing.get("promo_price") if pricing.get("promo_price") is not None else pricing.get("price")))
    }

    # Create or update order row; set status to 'checking' (or keep in checking/ready etc. but BR says status 'checking')
    if order is None:
        order = {
            "order_id": _gen_id("nc_ord_"),
            "account_id": account_id,
            "fqdn": fqdn_norm,
            "tld": tld,
            "term_years": term_years,
            "add_whois_guard": False,
            "contact_set_id": None,
            "availability_result": availability_result,
            "pricing_snapshot": pricing_snapshot,
            "namecheap_order_id": None,
            "namecheap_transaction_id": None,
            "status": "checking",
            "failure_code": None,
            "failure_message": None,
            "created_at": now,
            "updated_at": now
        }
        orders.append(order)
    else:
        # Transition to checking if needed, validate transitions
        transitions = {
            "draft": ["checking", "cancelled"],
            "checking": ["ready", "failed", "cancelled"],
            "ready": ["submitted", "cancelled"],
            "submitted": ["succeeded", "failed"],
            "succeeded": [],
            "failed": ["draft"],
            "cancelled": []
        }
        cur = order.get("status")
        if cur != "checking":
            if "checking" not in transitions.get(cur, []):
                _log("check_domain", "error", meta={"code": "INVALID_TRANSITION", "from": cur, "to": "checking"})
                return _err("INVALID_TRANSITION", f"Cannot transition order from {cur} to checking.", from_status=cur, to_status="checking")
            order["status"] = "checking"
        order["tld"] = tld
        order["term_years"] = term_years
        order["availability_result"] = availability_result
        order["pricing_snapshot"] = pricing_snapshot
        order["failure_code"] = None
        order["failure_message"] = None
        order["updated_at"] = now

    # If available, mark order ready (common backend behavior after check)
    if availability_result["available"]:
        transitions = {
            "draft": ["checking", "cancelled"],
            "checking": ["ready", "failed", "cancelled"],
            "ready": ["submitted", "cancelled"],
            "submitted": ["succeeded", "failed"],
            "succeeded": [],
            "failed": ["draft"],
            "cancelled": []
        }
        if order["status"] == "checking":
            if "ready" in transitions["checking"]:
                order["status"] = "ready"
                order["updated_at"] = now

    _save("domain_registration_orders.json", orders)

    body = {
        "order": order,
        "availability": availability_result,
        "pricing": pricing_snapshot
    }
    _log("check_domain", "ok", meta={"account_id": account_id, "fqdn": fqdn_norm})
    return body

def get_dns_hosts(domain_id, status=None, record_type=None, host=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "request_id": "req_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=24)),
                "endpoint": endpoint,
                "status": status_s,
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now,
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    if not isinstance(domain_id, str) or not re.match(r"^nc_dom_[A-Za-z0-9]{18,}$", domain_id):
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "domain_id is malformed.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if status is not None and (not isinstance(status, str) or status not in {"active", "deleted"}):
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status must be one of: active, deleted.")
    allowed_types = {"A","AAAA","CNAME","TXT","MX","NS","SRV","CAA","URL","URL301","FRAME"}
    if record_type is not None and (not isinstance(record_type, str) or record_type not in allowed_types):
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "record_type is invalid.", allowed=list(sorted(allowed_types)))
    if host is not None and not isinstance(host, str):
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "host must be a string.")
    if sort is None:
        sort = "created_at"
    if sort not in {"created_at","-created_at","updated_at","-updated_at","host","-host"}:
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort is invalid.")
    if cursor is not None and not isinstance(cursor, str):
        _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    domains = _load("domains.json")
    dom = next((d for d in domains if isinstance(d, dict) and d.get("domain_id") == domain_id), None)
    if not dom:
        _log("get_dns_hosts", "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "domain_id does not exist.")

    # Scope/auth: pick an active account that owns this domain
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("account_id") == dom.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        _log("get_dns_hosts", "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active connected account can access this domain.")

    dns = _load("dns_hosts.json")
    if not isinstance(dns, list):
        dns = []

    # Business rule: only return active; and if stale, simulate resync + soft-delete missing
    # Determine staleness using domain.last_synced_at
    def _parse_dt(x):
        if not x or not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                return datetime.datetime.fromisoformat(x[:-1])
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    last = _parse_dt(dom.get("last_synced_at"))
    stale = (last is None) or ((datetime.datetime.utcnow() - last) > datetime.timedelta(hours=6))

    # Simulate resync: if stale, update last_synced_at of existing active records; and soft-delete records that look orphaned
    # Orphan heuristic: if record hasn't been synced in > 30 days, mark deleted.
    if stale:
        changed = False
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=30)
        for r in dns:
            if not isinstance(r, dict) or r.get("domain_id") != domain_id:
                continue
            if r.get("status") == "active":
                ls = _parse_dt(r.get("last_synced_at"))
                if ls is not None and ls < cutoff:
                    # transition active -> deleted
                    r["status"] = "deleted"
                    r["updated_at"] = now
                    changed = True
                else:
                    r["last_synced_at"] = now
                    r["updated_at"] = now
                    changed = True
        if changed:
            _save("dns_hosts.json", dns)
        dom["last_synced_at"] = now
        dom["updated_at"] = now
        _save("domains.json", domains)

    # Filter; business rule says return only active rows (regardless of filter)
    rows = [r for r in dns if isinstance(r, dict) and r.get("domain_id") == domain_id and r.get("status") == "active"]
    if status is not None:
        # caller can request deleted, but backend rule forces active-only; return empty if asked for deleted
        if status != "active":
            rows = []
    if record_type is not None:
        rows = [r for r in rows if r.get("record_type") == record_type]
    if host is not None:
        rows = [r for r in rows if r.get("host") == host]

    # Sort
    reverse = sort.startswith("-")
    keyname = sort[1:] if reverse else sort
    def _key(r):
        v = r.get(keyname)
        return "" if v is None else v
    rows.sort(key=_key, reverse=reverse)

    # Cursor is an integer offset encoded as "off_<n>"
    offset = 0
    if cursor:
        m = re.match(r"^off_(\d+)$", cursor)
        if not m:
            _log("get_dns_hosts", "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        offset = int(m.group(1))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = f"off_{next_off}" if has_more else None

    _log("get_dns_hosts", "ok", meta={"domain_id": domain_id, "returned": len(page)})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort
        }
    }

def get_domain_contacts(domain_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "request_id": "req_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=24)),
                "endpoint": endpoint,
                "status": status_s,
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now,
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    if not isinstance(domain_id, str) or not re.match(r"^nc_dom_[A-Za-z0-9]{18,}$", domain_id):
        _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "domain_id is malformed.")
    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 50:
        _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 50.")
    if status is not None and (not isinstance(status, str) or status not in {"current","historical","pending_update"}):
        _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "status is invalid.")
    if sort is None:
        sort = "-created_at"
    if sort not in {"created_at","-created_at","updated_at","-updated_at","last_synced_at","-last_synced_at"}:
        _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "sort is invalid.")
    if cursor is not None and not isinstance(cursor, str):
        _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    domains = _load("domains.json")
    dom = next((d for d in domains if isinstance(d, dict) and d.get("domain_id") == domain_id), None)
    if not dom:
        _log("get_domain_contacts", "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "domain_id does not exist.")

    # Scope/auth: active account owning domain
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("account_id") == dom.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        _log("get_domain_contacts", "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active connected account can access this domain.")

    contacts = _load("domain_contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    def _parse_dt(x):
        if not x or not isinstance(x, str):
            return None
        try:
            if x.endswith("Z"):
                return datetime.datetime.fromisoformat(x[:-1])
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    # Find current contact set
    current = None
    for c in contacts:
        if isinstance(c, dict) and c.get("domain_id") == domain_id and c.get("status") == "current":
            current = c
            break

    # Staleness: if none exists or last_synced_at older than 7 days -> "sync" from Namecheap
    stale = True
    if current and _parse_dt(current.get("last_synced_at")):
        stale = (datetime.datetime.utcnow() - _parse_dt(current.get("last_synced_at"))) > datetime.timedelta(days=7)
    elif current and current.get("last_synced_at") == now:
        stale = False

    required_keys = ["FirstName","LastName","Address1","City","StateProvince","PostalCode","Country","Phone","Email"]
    def _default_contact():
        # Generate a plausible synced contact object
        return {
            "FirstName": "Domain",
            "LastName": "Owner",
            "Address1": "1 Registrar Way",
            "City": "Wilmington",
            "StateProvince": "DE",
            "PostalCode": "19801",
            "Country": "US",
            "Phone": "+1.3025550100",
            "Email": f"admin@{dom.get('fqdn','example.com')}"
        }

    def _gen_id(prefix):
        return prefix + "".join(random.choices(string.ascii_letters + string.digits, k=22))

    if stale:
        # demote previous current to historical (lifecycle: current -> historical allowed)
        changed = False
        for c in contacts:
            if not isinstance(c, dict) or c.get("domain_id") != domain_id:
                continue
            if c.get("status") == "current":
                c["status"] = "historical"
                c["updated_at"] = now
                changed = True

        new_set = {
            "contact_set_id": _gen_id("nc_cset_"),
            "domain_id": domain_id,
            "status": "current",
            "registrant": _default_contact(),
            "admin": _default_contact(),
            "tech": _default_contact(),
            "billing": _default_contact(),
            "source": "synced_from_namecheap",
            "last_synced_at": now,
            "created_at": now,
            "updated_at": now
        }
        # validate required keys
        for k in ("registrant","admin","tech","billing"):
            obj = new_set.get(k)
            if not isinstance(obj, dict) or any(rk not in obj or obj.get(rk) in (None, "") for rk in required_keys):
                _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
                return _err("VALIDATION_ERROR", f"{k} contact is missing required fields.")
        contacts.append(new_set)
        _save("domain_contacts.json", contacts)

    # Filter/sort/paginate
    rows = [c for c in contacts if isinstance(c, dict) and c.get("domain_id") == domain_id]
    if status is not None:
        rows = [c for c in rows if c.get("status") == status]

    reverse = sort.startswith("-")
    keyname = sort[1:] if reverse else sort
    def _key(r):
        v = r.get(keyname)
        return "" if v is None else v
    rows.sort(key=_key, reverse=reverse)

    offset = 0
    if cursor:
        m = re.match(r"^off_(\d+)$", cursor)
        if not m:
            _log("get_domain_contacts", "error", meta={"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor is invalid.")
        offset = int(m.group(1))

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = f"off_{next_off}" if has_more else None

    _log("get_domain_contacts", "ok", meta={"domain_id": domain_id, "returned": len(page)})
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort
        }
    }

def get_domain_info(domain_id, **_extra):
    import json, os, datetime, re, time, random, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_s, meta=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "request_id": "req_" + "".join(random.choices(string.ascii_lowercase + string.digits, k=24)),
                "endpoint": endpoint,
                "status": status_s,
                "latency_ms": int((time.time() - start) * 1000),
                "timestamp": now,
                "meta": meta or {}
            })
            _save("request_logs.json", logs)
        except Exception:
            return

    if not isinstance(domain_id, str) or not re.match(r"^nc_dom_[A-Za-z0-9]{18,}$", domain_id):
        _log("get_domain_info", "error", meta={"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "domain_id is malformed.")

    domains = _load("domains.json")
    dom = next((d for d in domains if isinstance(d, dict) and d.get("domain_id") == domain_id), None)
    if not dom:
        _log("get_domain_info", "error", meta={"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "domain_id does not exist.")

    # Scope/auth: must be owned by an active connected account
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if isinstance(a, dict) and a.get("account_id") == dom.get("account_id") and a.get("status") == "active"), None)
    if not acct:
        _log("get_domain_info", "error", meta={"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active connected account can access this domain.")

    _log("get_domain_info", "ok", meta={"domain_id": domain_id})
    return {"domain": dom}

def get_domain_list(account_id, status=None, tld=None, fqdn=None, search=None, auto_renew=None, whois_guard_enabled=None, expires_before=None, expires_after=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be a valid RFC3339 datetime string")

    def _dt_val(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                vv = v.strip()
                if vv.endswith("Z"):
                    vv = vv[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(vv)
            except Exception:
                return None
        return None

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^nc_acc_[A-Za-z0-9]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")

    allowed_status = {"active", "expired", "pending_transfer", "pending_delete", "suspended"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        return _err("VALIDATION_ERROR", "Invalid status filter", field="status", allowed=sorted(allowed_status))

    if tld is not None and not isinstance(tld, str):
        return _err("VALIDATION_ERROR", "tld must be a string", field="tld")
    if fqdn is not None and not isinstance(fqdn, str):
        return _err("VALIDATION_ERROR", "fqdn must be a string", field="fqdn")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string", field="search")
    if auto_renew is not None and not isinstance(auto_renew, bool):
        return _err("VALIDATION_ERROR", "auto_renew must be a boolean", field="auto_renew")
    if whois_guard_enabled is not None and not isinstance(whois_guard_enabled, bool):
        return _err("VALIDATION_ERROR", "whois_guard_enabled must be a boolean", field="whois_guard_enabled")

    try:
        dt_before = _parse_dt(expires_before, "expires_before")
        dt_after = _parse_dt(expires_after, "expires_after")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    allowed_sort = {"created_at", "-created_at", "expires_at", "-expires_at", "fqdn", "-fqdn", "updated_at", "-updated_at"}
    if sort is None:
        sort = "fqdn"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=sorted(allowed_sort))

    # Authenticate ambient: ensure account exists and is usable
    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("account_id") == account_id and a.get("status") == "active"), None)

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _log(status_code, error_code=None):
        request_logs.append({
            "request_id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get_domain_list",
            "account_id": account_id,
            "credential": None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "timestamp": _iso(now),
        })
        _save("request_logs.json", request_logs)

    if acct is None:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active account can serve this request")

    domains = _load("domains.json")
    if not isinstance(domains, list):
        domains = []

    # Scope by account_id (forbidden cross-account)
    rows = [d for d in domains if d.get("account_id") == account_id]

    # Filters
    if status is not None:
        rows = [d for d in rows if d.get("status") == status]
    if tld is not None:
        rows = [d for d in rows if isinstance(d.get("tld"), str) and d.get("tld") == tld]
    if fqdn is not None:
        rows = [d for d in rows if d.get("fqdn") == fqdn]
    if search is not None:
        s = search.lower()
        rows = [d for d in rows if isinstance(d.get("fqdn"), str) and s in d.get("fqdn").lower()]
    if auto_renew is not None:
        rows = [d for d in rows if d.get("auto_renew") is auto_renew]
    if whois_guard_enabled is not None:
        rows = [d for d in rows if d.get("whois_guard_enabled") is whois_guard_enabled]

    if dt_before is not None:
        def _before(d):
            v = _dt_val(d.get("expires_at"))
            return v is not None and v < dt_before
        rows = [d for d in rows if _before(d)]
    if dt_after is not None:
        def _after(d):
            v = _dt_val(d.get("expires_at"))
            return v is not None and v > dt_after
        rows = [d for d in rows if _after(d)]

    # Sorting
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _sort_key(d):
        v = d.get(key)
        if key in ("created_at", "updated_at", "expires_at", "created_at_registrar", "last_synced_at"):
            dv = _dt_val(v)
            # Ensure deterministic ordering even when missing: treat missing as far past for ascending
            return dv if dv is not None else (datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if not desc else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        if v is None:
            return ""
        return v

    rows.sort(key=_sort_key, reverse=desc)

    # Cursor pagination: cursor is integer offset encoded as string "o:<n>"
    offset = 0
    if cursor:
        if cursor.startswith("o:"):
            try:
                offset = int(cursor[2:])
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        else:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"o:{next_offset}" if has_more else None

    _log(200)
    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort
        }
    }

def get_tld_pricing(account_id, tld=None, currency=None, operation=None, duration_years=None, effective_at=None, include_expired=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError(f"{field} must be an RFC3339 datetime string")
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            raise ValueError(f"{field} must be a valid RFC3339 datetime string")

    def _dt_val(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if isinstance(v, str):
            try:
                vv = v.strip()
                if vv.endswith("Z"):
                    vv = vv[:-1] + "+00:00"
                return datetime.datetime.fromisoformat(vv)
            except Exception:
                return None
        return None

    def _gen_id(prefix):
        alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^nc_acc_[A-Za-z0-9]{18,}$", account_id):
        return _err("VALIDATION_ERROR", "account_id is malformed", field="account_id")

    if tld is not None and not isinstance(tld, str):
        return _err("VALIDATION_ERROR", "tld must be a string", field="tld")

    allowed_currency = {"USD", "EUR", "GBP", "CAD", "AUD"}
    if currency is not None and (not isinstance(currency, str) or currency not in allowed_currency):
        return _err("VALIDATION_ERROR", "Invalid currency", field="currency", allowed=sorted(allowed_currency))

    allowed_operation = {"register", "renew", "transfer", "redemption"}
    if operation is not None and (not isinstance(operation, str) or operation not in allowed_operation):
        return _err("VALIDATION_ERROR", "Invalid operation", field="operation", allowed=sorted(allowed_operation))

    if duration_years is not None:
        if not isinstance(duration_years, int) or duration_years < 1 or duration_years > 10:
            return _err("VALIDATION_ERROR", "duration_years must be between 1 and 10", field="duration_years")

    try:
        eff_at = _parse_dt(effective_at, "effective_at")
    except ValueError as e:
        return _err("VALIDATION_ERROR", str(e))

    if include_expired is not None and not isinstance(include_expired, bool):
        return _err("VALIDATION_ERROR", "include_expired must be a boolean", field="include_expired")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")

    allowed_sort = {"tld", "-tld", "price", "-price", "effective_at", "-effective_at", "updated_at", "-updated_at"}
    if sort is None:
        sort = "tld"
    if not isinstance(sort, str) or sort not in allowed_sort:
        return _err("VALIDATION_ERROR", "Invalid sort", field="sort", allowed=sorted(allowed_sort))

    accounts = _load("accounts.json")
    acct = next((a for a in accounts if a.get("account_id") == account_id and a.get("status") == "active"), None)

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _log(status_code, error_code=None):
        request_logs.append({
            "request_id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "get_tld_pricing",
            "account_id": account_id,
            "credential": None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "timestamp": _iso(now),
        })
        _save("request_logs.json", request_logs)

    if acct is None:
        _log(401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active account can serve this request")

    pricing = _load("tld_pricing.json")
    if not isinstance(pricing, list):
        pricing = []

    # Refresh from "Namecheap" when absent/expired for requested keys:
    # Since offline, we simulate refresh deterministically by inserting a new effective price row now.
    # We only refresh when the caller asks for a specific key (at least tld,currency,operation,duration_years).
    def _is_expired(row, at):
        ex = _dt_val(row.get("expires_at"))
        return ex is not None and ex <= at

    def _matches_filters(row):
        if tld is not None and row.get("tld") != tld:
            return False
        if currency is not None and row.get("currency") != currency:
            return False
        if operation is not None and row.get("operation") != operation:
            return False
        if duration_years is not None and row.get("duration_years") != duration_years:
            return False
        if eff_at is not None:
            ea = _dt_val(row.get("effective_at"))
            if ea is None or ea > eff_at:
                return False
        if not include_expired:
            if _is_expired(row, now):
                return False
        return True

    def _group_key(row):
        return (row.get("tld"), row.get("currency"), row.get("operation"), row.get("duration_years"), row.get("source_account_id"))

    # Determine if we should refresh: absent or only expired rows for requested specific key
    specific_key = (tld is not None and currency is not None and operation is not None and duration_years is not None)
    mutated = False
    if specific_key:
        key = (tld, currency, operation, duration_years, account_id)
        candidates = [r for r in pricing if _group_key(r) == key]
        usable = []
        for r in candidates:
            if eff_at is not None:
                ea = _dt_val(r.get("effective_at"))
                if ea is None or ea > eff_at:
                    continue
            if include_expired:
                usable.append(r)
            else:
                if not _is_expired(r, now):
                    usable.append(r)
        if len(usable) == 0:
            base_price = 8.0 + (hash((tld, currency, operation, duration_years, account_id)) % 4000) / 100.0
            promo = None
            if operation == "register" and duration_years == 1:
                promo = max(0.0, base_price - 1.5)
            new_row = {
                "tld_price_id": _gen_id("nc_tldp_"),
                "tld": tld,
                "currency": currency,
                "operation": operation,
                "duration_years": duration_years,
                "price": float(round(base_price, 2)),
                "promo_price": float(round(promo, 2)) if promo is not None else None,
                "is_premium_possible": True if tld not in ("com", "net", "org") else False,
                "effective_at": _iso(now),
                "expires_at": _iso(now + datetime.timedelta(days=7)),
                "source_account_id": account_id,
                "created_at": _iso(now),
                "updated_at": _iso(now),
            }
            # Enforce constraints
            if new_row["duration_years"] < 1 or new_row["duration_years"] > 10 or new_row["price"] < 0 or (new_row["promo_price"] is not None and new_row["promo_price"] < 0):
                _log(500, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Generated pricing violated constraints")
            pricing.append(new_row)
            mutated = True

    # Filter rows
    rows = [r for r in pricing if _matches_filters(r)]

    # "Most recent non-expired per group" unless include_expired explicitly True
    if not include_expired:
        best = {}
        for r in rows:
            gk = _group_key(r)
            ea = _dt_val(r.get("effective_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            cur = best.get(gk)
            if cur is None:
                best[gk] = r
            else:
                cea = _dt_val(cur.get("effective_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                if ea > cea:
                    best[gk] = r
        rows = list(best.values())

    # Sorting
    desc = sort.startswith("-")
    keyname = sort[1:] if desc else sort

    def _sort_key(r):
        v = r.get(keyname)
        if keyname in ("effective_at", "updated_at", "expires_at", "created_at"):
            dv = _dt_val(v)
            return dv if dv is not None else (datetime.datetime.max.replace(tzinfo=datetime.timezone.utc) if not desc else datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
        if keyname == "price":
            try:
                return float(v)
            except Exception:
                return float("inf") if not desc else float("-inf")
        if v is None:
            return ""
        return v

    rows.sort(key=_sort_key, reverse=desc)

    # Cursor pagination
    offset = 0
    if cursor:
        if cursor.startswith("o:"):
            try:
                offset = int(cursor[2:])
                if offset < 0:
                    raise ValueError()
            except Exception:
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")
        else:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"o:{next_offset}" if has_more else None

    if mutated:
        for r in pricing:
            if isinstance(r, dict) and "updated_at" in r and r.get("updated_at") is None:
                r["updated_at"] = _iso(now)
        _save("tld_pricing.json", pricing)

    _log(200)
    return {
        "object": "list",
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort
        }
    }

def register_domain(account_id, fqdn, term_years, add_whois_guard=None, contact_set=None, **_extra):
    import json, os, datetime, re, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "register_domain"
    credential_used = None

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_str, error_code=None):
        req = _load("request_log.json")
        if not isinstance(req, list):
            req = []
        now = _utcnow()
        req.append(
            {
                "request_id": "req_" + os.urandom(9).hex(),
                "endpoint": endpoint,
                "credential_used": credential_used,
                "status": status_str,
                "error_code": error_code,
                "timestamp": _iso(now),
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_log.json", req)

    # Simple global rate limit using request log (observably enforced)
    def _rate_limit_check():
        req = _load("request_log.json")
        if not isinstance(req, list):
            return None
        now = _utcnow()
        window_s = 60
        limit = 120
        cnt = 0
        for r in req:
            ts = _parse_dt(r.get("timestamp"))
            if not ts:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded; retry later.", limit=limit, window_seconds=window_s)
        return None

    def _gen_id(prefix):
        alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _parse_fqdn(s):
        if not isinstance(s, str):
            return None
        s = s.strip().lower().rstrip(".")
        if len(s) < 3 or len(s) > 253:
            return None
        labels = s.split(".")
        if len(labels) < 2:
            return None
        label_re = re.compile(r"^(xn--[a-z0-9-]{1,59}|[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)$")
        for lab in labels:
            if len(lab) < 1 or len(lab) > 63:
                return None
            if not label_re.match(lab):
                return None
        tld = labels[-1]
        if not re.match(r"^(xn--[a-z0-9-]{2,59}|[a-z0-9]{2,63})$", tld):
            return None
        return s

    def _split_domain(norm_fqdn):
        parts = norm_fqdn.split(".")
        return parts[-2], parts[-1]

    def _allowed_transition(cur, nxt):
        transitions = {
            "draft": ["checking", "cancelled"],
            "checking": ["ready", "failed", "cancelled"],
            "ready": ["submitted", "cancelled"],
            "submitted": ["succeeded", "failed"],
            "succeeded": [],
            "failed": ["draft"],
            "cancelled": [],
        }
        return nxt in transitions.get(cur, [])

    # Rate limit
    rl = _rate_limit_check()
    if rl:
        _log("error", "RATE_LIMIT")
        return rl

    # Validate inputs
    if not isinstance(account_id, str) or not re.match(r"^nc_acc_[A-Za-z0-9]{18,}$", account_id or ""):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "account_id is malformed.", field="account_id")

    norm_fqdn = _parse_fqdn(fqdn)
    if norm_fqdn is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "fqdn must be a valid domain name.", field="fqdn")

    if not isinstance(term_years, int) or term_years < 1 or term_years > 10:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "term_years must be an integer between 1 and 10.", field="term_years")

    if add_whois_guard is not None and not isinstance(add_whois_guard, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "add_whois_guard must be boolean.", field="add_whois_guard")

    if not isinstance(contact_set, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "contact_set must be an object.", field="contact_set")

    for sec in ["registrant", "admin", "tech", "billing"]:
        if sec not in contact_set:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"contact_set.{sec} is required.", field=f"contact_set.{sec}")
        if not isinstance(contact_set.get(sec), dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"contact_set.{sec} must be an object.", field=f"contact_set.{sec}")

    # IMPORTANT: Accept empty contact objects here (do not reject) because the datastore/business flows
    # can support reusing an existing contact_set_id or syncing later; reject only missing required sections.
    # (The schema-level "required keys" applies at domain_contacts API boundary; register_domain takes a
    # vendor-style contact_set payload but this service must accept valid parameter schema inputs.)

    # Authenticate/resolve account context (ambient auth; choose any active account matching account_id)
    accounts = _load("accounts.json")
    if isinstance(accounts, dict) and "rows" in accounts:
        accounts = accounts.get("rows")  # defensive; but store appears list
    if not isinstance(accounts, list):
        accounts = []
    acct = None
    for a in accounts:
        if a.get("account_id") == account_id and a.get("status") == "active":
            acct = a
            break
    if acct is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active connected account can serve this request.", account_id=account_id)

    now = _utcnow()
    sld, tld = _split_domain(norm_fqdn)

    # Load orders, find or create a non-terminal order (draft/checking/ready/submitted) for this account+fqdn
    orders = _load("domain_registration_orders.json")
    if not isinstance(orders, list):
        orders = []
    non_terminal = {"draft", "checking", "ready", "submitted"}
    existing = None
    for o in orders:
        if o.get("account_id") == account_id and (o.get("fqdn") or "").lower() == norm_fqdn and o.get("status") in non_terminal:
            existing = o
            break

    # Create a domain_contacts row for this contact_set (source=provided_for_registration) so we can reference it
    domain_contacts = _load("domain_contacts.json")
    if not isinstance(domain_contacts, list):
        domain_contacts = []
    contact_set_id = _gen_id("nc_con_")
    contact_row = {
        "contact_set_id": contact_set_id,
        "domain_id": "__pending__:" + account_id + ":" + norm_fqdn,
        "status": "pending_update",
        "registrant": contact_set.get("registrant", {}),
        "admin": contact_set.get("admin", {}),
        "tech": contact_set.get("tech", {}),
        "billing": contact_set.get("billing", {}),
        "source": "provided_for_registration",
        "last_synced_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    domain_contacts.append(contact_row)
    _save("domain_contacts.json", domain_contacts)

    # Build/refresh availability result (simulate; real system would call Namecheap)
    # If already registered in our domains table for same account, treat as taken.
    domains = _load("domains.json")
    if not isinstance(domains, list):
        domains = []
    already_owned = any(d.get("account_id") == account_id and (d.get("fqdn") or "").lower() == norm_fqdn and d.get("status") in ["active", "expired", "pending_transfer", "pending_delete", "suspended"] for d in domains)

    availability = {
        "fqdn": norm_fqdn,
        "checked_at": _iso(now),
        "available": not already_owned,
        "is_premium": False,
        "tld": tld,
    }

    # Pricing snapshot: attempt to use existing tld_pricing, else create a simple row
    pricing_rows = _load("tld_pricing.json")
    if not isinstance(pricing_rows, list):
        pricing_rows = []

    def _most_recent_pricing(tld_, currency_, operation_, duration_, source_account_id_):
        best = None
        best_eff = None
        for r in pricing_rows:
            if r.get("tld") != tld_:
                continue
            if r.get("currency") != currency_:
                continue
            if r.get("operation") != operation_:
                continue
            if r.get("duration_years") != duration_:
                continue
            if (r.get("source_account_id") or None) != (source_account_id_ or None):
                continue
            exp = _parse_dt(r.get("expires_at"))
            if exp is not None and exp <= now:
                continue
            eff = _parse_dt(r.get("effective_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            if best is None or eff > best_eff:
                best = r
                best_eff = eff
        return best

    currency = "USD"
    pr = _most_recent_pricing(tld, currency, "register", term_years, account_id)
    if pr is None:
        # Upsert a minimal price row (valid constraints)
        price_val = float(12.98 * term_years)
        tld_price_id = _gen_id("nc_tldp_")
        pr = {
            "tld_price_id": tld_price_id,
            "tld": tld,
            "currency": currency,
            "operation": "register",
            "duration_years": term_years,
            "price": price_val,
            "promo_price": None,
            "is_premium_possible": True,
            "effective_at": _iso(now),
            "expires_at": _iso(now + datetime.timedelta(days=30)),
            "source_account_id": account_id,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        pricing_rows.append(pr)
        _save("tld_pricing.json", pricing_rows)

    subtotal = pr.get("promo_price") if pr.get("promo_price") is not None else pr.get("price")
    if not isinstance(subtotal, (int, float)) or subtotal < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Pricing data is invalid (non-negative price required).", field="tld_pricing.price")

    pricing_snapshot = {
        "currency": pr.get("currency"),
        "operation": "register",
        "duration_years": term_years,
        "unit_price": float(subtotal) / float(term_years) if term_years else float(subtotal),
        "subtotal": float(subtotal),
        "promo_applied": pr.get("promo_price") is not None,
        "whois_guard": bool(add_whois_guard) if add_whois_guard is not None else False,
        "estimated_total": float(subtotal),
        "priced_at": _iso(now),
    }

    # Create or update order, ensuring uniqueness among non-terminal statuses
    if existing is None:
        order_id = _gen_id("nc_ord_")
        order = {
            "order_id": order_id,
            "account_id": account_id,
            "fqdn": norm_fqdn,
            "tld": tld,
            "term_years": term_years,
            "add_whois_guard": bool(add_whois_guard) if add_whois_guard is not None else False,
            "contact_set_id": contact_set_id,
            "availability_result": availability,
            "pricing_snapshot": pricing_snapshot,
            "namecheap_order_id": None,
            "namecheap_transaction_id": None,
            "status": "ready" if availability.get("available") else "failed",
            "failure_code": None if availability.get("available") else "DOMAIN_TAKEN",
            "failure_message": None if availability.get("available") else "Domain is already registered.",
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        orders.append(order)
    else:
        # Only update permitted fields; do not claim success if cannot proceed due to terminal status.
        existing["term_years"] = term_years
        existing["add_whois_guard"] = bool(add_whois_guard) if add_whois_guard is not None else existing.get("add_whois_guard", False)
        existing["contact_set_id"] = contact_set_id
        existing["availability_result"] = availability
        existing["pricing_snapshot"] = pricing_snapshot
        existing["tld"] = tld
        existing["updated_at"] = _iso(now)
        order = existing

        # If availability says not available, move to failed if allowed
        if not availability.get("available"):
            if order.get("status") in ["draft", "checking", "ready"]:
                if _allowed_transition(order["status"], "failed"):
                    order["status"] = "failed"
                    order["failure_code"] = "DOMAIN_TAKEN"
                    order["failure_message"] = "Domain is already registered."
                    order["updated_at"] = _iso(now)

    # Persist order changes
    _save("domain_registration_orders.json", orders)

    # If not available, return the order as failed (no further mutation)
    if not availability.get("available"):
        _log("ok", None)
        return {"order": order, "domain": None}

    # Proceed to submit (status must be ready, or transition from draft/checking to ready then submitted)
    cur_status = order.get("status")
    if cur_status in ["draft", "checking"]:
        # promote to ready if allowed
        if _allowed_transition(cur_status, "ready"):
            order["status"] = "ready"
            order["updated_at"] = _iso(now)
        cur_status = order.get("status")

    if cur_status != "ready":
        _log("error", "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            "register_domain can only submit an order when status is 'ready' (or convertible from 'draft'/'checking' after a successful availability check).",
            order_id=order.get("order_id"),
            current_status=cur_status,
            required_status="ready",
        )

    # Transition to submitted
    if not _allowed_transition(order["status"], "submitted"):
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Order status transition to 'submitted' is not allowed.", order_id=order.get("order_id"), from_status=order.get("status"), to_status="submitted")

    order["status"] = "submitted"
    order["updated_at"] = _iso(now)
    _save("domain_registration_orders.json", orders)

    # Simulate registrar response success
    registrar_ok = True

    now2 = _utcnow()
    if registrar_ok:
        if not _allowed_transition(order["status"], "succeeded"):
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Order status transition to 'succeeded' is not allowed.", order_id=order.get("order_id"), from_status=order.get("status"), to_status="succeeded")

        order["status"] = "succeeded"
        order["namecheap_order_id"] = order.get("namecheap_order_id") or ("nc_order_" + os.urandom(6).hex())
        order["namecheap_transaction_id"] = order.get("namecheap_transaction_id") or ("nc_txn_" + os.urandom(6).hex())
        order["failure_code"] = None
        order["failure_message"] = None
        order["updated_at"] = _iso(now2)
        _save("domain_registration_orders.json", orders)

        # Upsert domain row
        domains = _load("domains.json")
        if not isinstance(domains, list):
            domains = []
        dom = None
        for d in domains:
            if d.get("account_id") == account_id and (d.get("fqdn") or "").lower() == norm_fqdn:
                dom = d
                break

        if dom is None:
            dom = {
                "domain_id": _gen_id("nc_dom_"),
                "account_id": account_id,
                "fqdn": norm_fqdn,
                "sld": sld,
                "tld": tld,
                "status": "active",
                "auto_renew": True,
                "whois_guard_enabled": bool(order.get("add_whois_guard")),
                "nameservers": None,
                "created_at_registrar": _iso(now2),
                "expires_at": _iso(now2 + datetime.timedelta(days=365 * term_years)),
                "last_synced_at": _iso(now2),
                "created_at": _iso(now2),
                "updated_at": _iso(now2),
            }
            domains.append(dom)
        else:
            # enforce allowed domain transitions: anything -> active is not always allowed; but on registration we set active
            dom["status"] = "active"
            dom["tld"] = tld
            dom["sld"] = sld
            dom["whois_guard_enabled"] = bool(order.get("add_whois_guard"))
            dom["last_synced_at"] = _iso(now2)
            if dom.get("expires_at") is None:
                dom["expires_at"] = _iso(now2 + datetime.timedelta(days=365 * term_years))
            dom["updated_at"] = _iso(now2)
        _save("domains.json", domains)

        # Attach contact set to real domain: set current and demote any previous current to historical
        domain_contacts = _load("domain_contacts.json")
        if not isinstance(domain_contacts, list):
            domain_contacts = []
        # demote existing current rows for this domain
        for r in domain_contacts:
            if r.get("domain_id") == dom["domain_id"] and r.get("status") == "current":
                r["status"] = "historical"
                r["updated_at"] = _iso(now2)
        # update our pending contact row
        for r in domain_contacts:
            if r.get("contact_set_id") == contact_set_id:
                r["domain_id"] = dom["domain_id"]
                # transition pending_update -> current allowed
                if r.get("status") in ["pending_update"]:
                    r["status"] = "current"
                elif r.get("status") == "current":
                    pass
                else:
                    # if it was something else, keep but do not violate lifecycle by forcing
                    pass
                r["updated_at"] = _iso(now2)
                break
        _save("domain_contacts.json", domain_contacts)

        _log("ok", None)
        return {"order": order, "domain": dom}

    # Failure path
    if not _allowed_transition(order["status"], "failed"):
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Order status transition to 'failed' is not allowed.", order_id=order.get("order_id"), from_status=order.get("status"), to_status="failed")
    order["status"] = "failed"
    order["failure_code"] = "PAYMENT_DECLINED"
    order["failure_message"] = "Card was declined by issuer; please use a different payment method."
    order["updated_at"] = _iso(now2)
    _save("domain_registration_orders.json", orders)
    _log("ok", None)
    return {"order": order, "domain": None}

def create_domain_registration_order(fqdn, term_years, currency=None, add_whois_guard=None, contact_set_id=None, **_extra):
    import json, os, datetime, re, time, random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"
        return prefix + "".join(random.choice(alphabet) for _ in range(22))

    def _parse_fqdn(s):
        if not isinstance(s, str):
            return None
        s = s.strip().lower().rstrip(".")
        if len(s) < 3 or len(s) > 253:
            return None
        labels = s.split(".")
        if len(labels) < 2:
            return None
        label_re = re.compile(r"^(xn--[a-z0-9-]{1,59}|[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)$")
        for lab in labels:
            if len(lab) < 1 or len(lab) > 63:
                return None
            if not label_re.match(lab):
                return None
        tld = labels[-1]
        if not re.match(r"^(xn--[a-z0-9-]{2,59}|[a-z0-9]{2,63})$", tld):
            return None
        return s

    # Validate inputs
    norm_fqdn = _parse_fqdn(fqdn)
    if norm_fqdn is None:
        return _err("VALIDATION_ERROR", "fqdn is malformed", field="fqdn")
    if not isinstance(term_years, int) or term_years < 1 or term_years > 10:
        return _err("VALIDATION_ERROR", "term_years must be between 1 and 10", field="term_years")

    allowed_currency = {"USD", "EUR", "GBP", "CAD", "AUD"}
    if currency is not None and (not isinstance(currency, str) or currency not in allowed_currency):
        return _err("VALIDATION_ERROR", "Invalid currency", field="currency", allowed=sorted(allowed_currency))
    if add_whois_guard is not None and not isinstance(add_whois_guard, bool):
        return _err("VALIDATION_ERROR", "add_whois_guard must be a boolean", field="add_whois_guard")
    if contact_set_id is not None:
        if not isinstance(contact_set_id, str) or not re.match(r"^nc_con_[A-Za-z0-9]{18,}$", contact_set_id):
            return _err("VALIDATION_ERROR", "contact_set_id is malformed", field="contact_set_id")

    accounts = _load("accounts.json")

    # Ambient authentication: pick a working active account (cannot infer from params otherwise).
    acct = next((a for a in accounts if a.get("status") == "active"), None)

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []

    def _log(status_code, error_code=None, account_id=None):
        request_logs.append({
            "request_id": f"req_{int(time.time()*1000)}_{os.getpid()}",
            "endpoint": "create_domain_registration_order",
            "account_id": account_id,
            "credential": None,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - started) * 1000),
            "timestamp": _iso(now),
        })
        _save("request_logs.json", request_logs)

    if acct is None:
        _log(401, "UNAUTHORIZED", None)
        return _err("UNAUTHORIZED", "No active account can serve this request")

    account_id = acct.get("account_id")

    orders = _load("domain_registration_orders.json")
    if not isinstance(orders, list):
        orders = []
    contacts = _load("domain_contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    # Validate contact_set_id exists if provided
    if contact_set_id is not None:
        if not any(c.get("contact_set_id") == contact_set_id for c in contacts):
            _log(404, "NOT_FOUND", account_id)
            return _err("NOT_FOUND", "contact_set_id not found", contact_set_id=contact_set_id)

    non_terminal = {"draft", "checking", "ready", "submitted"}
    existing = [o for o in orders if o.get("account_id") == account_id and o.get("fqdn") == norm_fqdn and o.get("status") in non_terminal]
    # Return an existing order instead of duplicate (prefer draft/ready/checking/submitted)
    rank = {"draft": 0, "ready": 1, "checking": 2, "submitted": 3}
    existing.sort(key=lambda o: rank.get(o.get("status"), 99))
    if existing:
        o = existing[0]
        # update desired term/currency/addon/contact ref idempotently
        o["term_years"] = term_years
        if currency is not None:
            # capture pricing context in snapshot, not a schema field; store in pricing_snapshot
            ps = o.get("pricing_snapshot") if isinstance(o.get("pricing_snapshot"), dict) else {}
            ps["currency"] = currency
            o["pricing_snapshot"] = ps
        if add_whois_guard is not None:
            o["add_whois_guard"] = add_whois_guard
        if contact_set_id is not None:
            o["contact_set_id"] = contact_set_id
        o["updated_at"] = _iso(now)
        _save("domain_registration_orders.json", orders)
        _log(200, None, account_id)
        return {"order": o, "reused": True}

    tld = norm_fqdn.split(".")[-1]
    order = {
        "order_id": _gen_id("nc_ord_"),
        "account_id": account_id,
        "fqdn": norm_fqdn,
        "tld": tld,
        "term_years": term_years,
        "add_whois_guard": bool(add_whois_guard) if add_whois_guard is not None else False,
        "contact_set_id": contact_set_id,
        "availability_result": None,
        "pricing_snapshot": {"currency": currency} if currency is not None else None,
        "namecheap_order_id": None,
        "namecheap_transaction_id": None,
        "status": "draft",
        "failure_code": None,
        "failure_message": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    # Enforce uniqueness constraint for non-terminal statuses:
    if any(o.get("account_id") == account_id and o.get("fqdn") == norm_fqdn and o.get("status") in non_terminal for o in orders):
        _log(409, "CONFLICT", account_id)
        return _err("CONFLICT", "A non-terminal order already exists for this account and fqdn")

    orders.append(order)
    _save("domain_registration_orders.json", orders)

    _log(200, None, account_id)
    return {"order": order, "reused": False}

