    # Ambient auth resolution: pick any active account (tool has no explicit credential parameter)
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
    if not active_accounts:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context is available to serve this request.")

    # Enforce account scoping: order must be owned by the authenticated account.
    # Since credentials are ambient and not provided, resolve to an account that actually owns the order.
    order = None
