    return {
        "order": order
    }

def update_domain_registration_order(order_id, term_years=None, add_whois_guard=None, contact_set_id=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_domain_registration_order"
    credential_used = None  # ambient auth (no explicit credential parameter)

    def _utcnow():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _append_request_log(status_str, error_code=None):
        req = _load("request_log.json")
        if not isinstance(req, list):
            req = []
        now = _utcnow()
        req.append(
            {
                "request_id": "req_" + os.urandom(9).hex(),
                "endpoint": endpoint,
                "credential_used": credential_used,
                "status": status_str,
                "error_code": error_code,
                "timestamp": _iso(now),
                "latency_ms": int((time.time() - t0) * 1000),
            }
        )
        _save("request_log.json", req)

    def _rate_limit_check():
        # Simple per-endpoint sliding window rate limit (observable via request_log.json)
        req = _load("request_log.json")
        if not isinstance(req, list):
            return None
        now = _utcnow()
        window_s = 60
        limit = 180
        cnt = 0
        for r in req:
            if r.get("endpoint") != endpoint:
                continue
            ts = _parse_dt(r.get("timestamp"))
            if ts is None:
                continue
            if (now - ts).total_seconds() <= window_s:
                cnt += 1
                if cnt >= limit:
                    return _err("RATE_LIMIT", f"Rate limit exceeded for {endpoint}: {limit} requests per {window_s}s.")
        return None

    def _lifecycle_allowed_next(cur):
        transitions = {
            "draft": ["checking", "cancelled"],
            "checking": ["ready", "failed", "cancelled"],
            "ready": ["submitted", "cancelled"],
            "submitted": ["succeeded", "failed"],
            "succeeded": [],
            "failed": ["draft"],
            "cancelled": [],
        }
        return transitions.get(cur, [])

    def _is_terminal(st):
        return st in ("succeeded", "cancelled")

    # ---- validate inputs (before any mutation) ----
    if not isinstance(order_id, str) or not re.match(r"^nc_ord_[A-Za-z0-9]{18,}$", order_id):
        rl = _rate_limit_check()
        if rl:
            _append_request_log("error", rl["error"]["code"])
            return rl
        e = _err("VALIDATION_ERROR", "order_id is malformed; expected pattern ^nc_ord_[A-Za-z0-9]{18,}$.", order_id=order_id)
        _append_request_log("error", e["error"]["code"])
        return e

    if term_years is not None:
        if not isinstance(term_years, int) or isinstance(term_years, bool) or term_years < 1 or term_years > 10:
            rl = _rate_limit_check()
            if rl:
                _append_request_log("error", rl["error"]["code"])
                return rl
            e = _err("VALIDATION_ERROR", "term_years must be an integer in [1,10].", term_years=term_years)
            _append_request_log("error", e["error"]["code"])
            return e

    if add_whois_guard is not None and not isinstance(add_whois_guard, bool):
        rl = _rate_limit_check()
        if rl:
            _append_request_log("error", rl["error"]["code"])
            return rl
        e = _err("VALIDATION_ERROR", "add_whois_guard must be boolean when provided.", add_whois_guard=add_whois_guard)
        _append_request_log("error", e["error"]["code"])
        return e

    if contact_set_id is not None:
        if not isinstance(contact_set_id, str) or not re.match(r"^nc_con_[A-Za-z0-9]{18,}$", contact_set_id):
            rl = _rate_limit_check()
            if rl:
                _append_request_log("error", rl["error"]["code"])
                return rl
            e = _err(
                "VALIDATION_ERROR",
                "contact_set_id is malformed; expected pattern ^nc_con_[A-Za-z0-9]{18,}$.",
                contact_set_id=contact_set_id,
            )
            _append_request_log("error", e["error"]["code"])
            return e

    if status is not None:
        allowed = {"draft", "checking", "ready", "submitted", "succeeded", "failed", "cancelled"}
        if not isinstance(status, str) or status not in allowed:
            rl = _rate_limit_check()
            if rl:
                _append_request_log("error", rl["error"]["code"])
                return rl
            e = _err("VALIDATION_ERROR", "status must be one of: draft, checking, ready, submitted, succeeded, failed, cancelled.", status=status)
            _append_request_log("error", e["error"]["code"])
            return e

    # ---- rate limit enforcement ----
    rl = _rate_limit_check()
    if rl:
        _append_request_log("error", rl["error"]["code"])
        return rl

    # ---- load order and related refs ----
    orders = _load("domain_registration_orders.json")
    if not isinstance(orders, list):
        orders = []

    idx = None
    order = None
    for i, r in enumerate(orders):
        if isinstance(r, dict) and r.get("order_id") == order_id:
            idx = i
            order = r
            break

    if order is None:
        e = _err("NOT_FOUND", "Order not found.", order_id=order_id)
        _append_request_log("error", e["error"]["code"])
        return e

    cur_status = order.get("status")
    if cur_status not in {"draft", "checking", "ready", "submitted", "succeeded", "failed", "cancelled"}:
        e = _err("VALIDATION_ERROR", "Order has an unknown status in datastore; cannot update safely.", order_id=order_id, current_status=cur_status)
        _append_request_log("error", e["error"]["code"])
        return e

    # ---- enforce terminal-order update rules ----
    # Real behaviour: terminal orders cannot be edited. However, treat "no-op" updates as idempotent success.
    any_field_update = term_years is not None or add_whois_guard is not None or contact_set_id is not None
    requested_transition = status is not None and status != cur_status

    if _is_terminal(cur_status):
        # allow no-op (including status==current) as idempotent read-your-write confirmation
        if not any_field_update and not requested_transition:
            _append_request_log("success", None)
            return {
                "order": order,
                "updated": False,
            }
        # allow explicit retry workflow for failed only; succeeded/cancelled are immutable
        e = _err(
            "INVALID_TRANSITION",
            "Order is in a terminal state and cannot be modified (business rule: terminal orders are immutable).",
            order_id=order_id,
            current_status=cur_status,
            requested_status=status,
            allowed_next=_lifecycle_allowed_next(cur_status),
        )
        _append_request_log("error", e["error"]["code"])
        return e

    # ---- validate and enforce status transition (if requested) ----
    new_status = cur_status
    if status is not None:
        if status == cur_status:
            # idempotent: no transition
            new_status = cur_status
        else:
            allowed_next = _lifecycle_allowed_next(cur_status)
            if status not in allowed_next:
                # IMPORTANT: vendor contract says: "Raises VALIDATION_ERROR if ... requested transition is not allowed."
                e = _err(
                    "VALIDATION_ERROR",
                    "Requested status transition is not allowed by the order lifecycle (business rule: enforce lifecycle transitions).",
                    order_id=order_id,
                    current_status=cur_status,
                    requested_status=status,
                    allowed_next=allowed_next,
                )
                _append_request_log("error", e["error"]["code"])
                return e
            new_status = status

    # ---- validate contact_set reference (if provided) ----
    if contact_set_id is not None:
        contacts = _load("domain_contacts.json")
        if not isinstance(contacts, list):
            contacts = []
        found = False
        for c in contacts:
            if isinstance(c, dict) and c.get("contact_set_id") == contact_set_id:
                found = True
                break
        if not found:
            e = _err("NOT_FOUND", "contact_set_id does not exist.", contact_set_id=contact_set_id)
            _append_request_log("error", e["error"]["code"])
            return e

    # ---- enforce uniqueness constraint for non-terminal orders ----
    # unique(account_id, fqdn, status) where status in ('draft','checking','ready','submitted')
    target_account_id = order.get("account_id")
    target_fqdn = order.get("fqdn")
    active_statuses = {"draft", "checking", "ready", "submitted"}
    if new_status in active_statuses:
        for r in orders:
            if not isinstance(r, dict):
                continue
            if r.get("order_id") == order_id:
                continue
            if r.get("account_id") == target_account_id and r.get("fqdn") == target_fqdn and r.get("status") == new_status:
                e = _err(
                    "CONFLICT",
                    "Uniqueness constraint violation: an order with this account_id+fqdn already exists in the requested non-terminal status.",
                    account_id=target_account_id,
                    fqdn=target_fqdn,
                    status=new_status,
                    conflicting_order_id=r.get("order_id"),
                )
                _append_request_log("error", e["error"]["code"])
                return e

    # ---- apply updates; enforce "no success without effect" ----
    before = dict(order)
    changed = False

    if term_years is not None and order.get("term_years") != term_years:
        order["term_years"] = term_years
        changed = True

    if add_whois_guard is not None and order.get("add_whois_guard") != add_whois_guard:
        order["add_whois_guard"] = add_whois_guard
        changed = True

    if contact_set_id is not None and order.get("contact_set_id") != contact_set_id:
        order["contact_set_id"] = contact_set_id
        changed = True

    if new_status != cur_status:
        order["status"] = new_status
        changed = True

    if not changed:
        # idempotent update: return current resource, but indicate no change
        _append_request_log("success", None)
        return {"order": order, "updated": False}

    order["updated_at"] = _iso(_utcnow())
    # preserve created_at; if missing, set it (repair)
    if not order.get("created_at"):
        order["created_at"] = order["updated_at"]

    orders[idx] = order
    _save("domain_registration_orders.json", orders)

    _append_request_log("success", None)
    return {
        "order": order,
        "updated": True,
        "previous": before,
    }

def set_dns_hosts(domain_id, hosts, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0440000" if __import__("os").path.isdir("./environment_mix/0440000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "set_dns_hosts"
    credential_used = None

    def _log(status_str, error_code=None):
        req = _load("request_log.json")
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        row = {
            "request_id": "req_" + os.urandom(9).hex(),
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status_str,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(req, list):
            req.append(row)
            _save("request_log.json", req)

    # Validation
    if not isinstance(domain_id, str) or not re.match(r"^nc_dom_[A-Za-z0-9]{18,}$", domain_id or ""):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "domain_id is malformed.", field="domain_id")

    if not isinstance(hosts, list):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "hosts must be an array.", field="hosts")

    allowed_types = {"A", "AAAA", "CNAME", "TXT", "MX", "NS", "SRV", "CAA", "URL", "URL301", "FRAME"}

    # Validate hosts items and enforce request-set uniqueness (active uniqueness constraint)
    desired = []
    seen_keys = set()
    for idx, h in enumerate(hosts):
        if not isinstance(h, dict):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Each host record must be an object.", index=idx)
        # required keys
        for k in ("host", "record_type", "value"):
            if k not in h:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"Missing required field: {k}.", index=idx, field=k)
        host = h.get("host")
        rtype = h.get("record_type")
        value = h.get("value")
        ttl = h.get("ttl", None)
        mx_pref = h.get("mx_pref", None)
        is_frozen = h.get("is_frozen", None)

        if not isinstance(host, str) or host == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "host must be a non-empty string.", index=idx, field="host")
        if not isinstance(rtype, str) or rtype not in allowed_types:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "record_type is invalid.", index=idx, field="record_type", allowed=sorted(list(allowed_types)))
        if not isinstance(value, str) or value == "":
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "value must be a non-empty string.", index=idx, field="value")

        if ttl is not None:
            if not isinstance(ttl, int) or ttl < 60 or ttl > 86400:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "ttl must be an integer between 60 and 86400 when provided.", index=idx, field="ttl")

        if mx_pref is not None:
            if not isinstance(mx_pref, int) or mx_pref < 0 or mx_pref > 65535:
                _log("error", "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "mx_pref must be an integer between 0 and 65535 when provided.", index=idx, field="mx_pref")
        if rtype == "MX" and mx_pref is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "mx_pref is required for MX records.", index=idx, field="mx_pref")

        if is_frozen is not None and not isinstance(is_frozen, bool):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "is_frozen must be boolean when provided.", index=idx, field="is_frozen")

        key = (host, rtype, value, mx_pref if mx_pref is not None else -1)
        if key in seen_keys:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "Duplicate active DNS record in requested set.", index=idx, key={"host": host, "record_type": rtype, "value": value, "mx_pref": mx_pref})
        seen_keys.add(key)
        desired.append({
            "host": host,
            "record_type": rtype,
            "value": value,
            "ttl": ttl,
            "mx_pref": mx_pref,
            "is_frozen": bool(is_frozen) if is_frozen is not None else False,
        })

    accounts = _load("accounts.json")
    domains = _load("domains.json")
    dns_hosts = _load("dns_hosts.json")

    # Ambient auth: choose active account that owns the domain
    active_accounts = [a for a in accounts if isinstance(a, dict) and a.get("status") == "active"]
    if not active_accounts:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authenticated account context is available to serve this request.")

    domain = None
    for a in active_accounts:
        for d in domains:
            if isinstance(d, dict) and d.get("domain_id") == domain_id and d.get("account_id") == a.get("account_id"):
                domain = d
                credential_used = a.get("account_id")
                break
        if domain:
            break
    if not domain:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Domain not found for the authenticated account.", domain_id=domain_id)

    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Index existing active records for domain
    existing_active = []
    for r in dns_hosts:
        if isinstance(r, dict) and r.get("domain_id") == domain_id and r.get("status") == "active":
            existing_active.append(r)

    # Prepare lookups by unique key
    def _k(row):
        return (
            row.get("host"),
            row.get("record_type"),
            row.get("value"),
            row.get("mx_pref") if row.get("mx_pref") is not None else -1
        )

    existing_by_key = {_k(r): r for r in existing_active}

    desired_keys = set((r["host"], r["record_type"], r["value"], r["mx_pref"] if r["mx_pref"] is not None else -1) for r in desired)
    existing_keys = set(existing_by_key.keys())

    # Soft delete missing
    deleted_count = 0
    updated_count = 0
    inserted_count = 0

    # lifecycle for dns_hosts: active -> deleted only
    for i, r in enumerate(list(dns_hosts)):
        if not isinstance(r, dict):
            continue
        if r.get("domain_id") != domain_id:
            continue
        if r.get("status") != "active":
            continue
        rk = _k(r)
        if rk not in desired_keys:
            # transition to deleted
            r["status"] = "deleted"
            r["updated_at"] = now
            dns_hosts[i] = r
            deleted_count += 1

    # Upsert desired as active
    for r in desired:
        rk = (r["host"], r["record_type"], r["value"], r["mx_pref"] if r["mx_pref"] is not None else -1)
        existing = existing_by_key.get(rk)
        if existing:
            # Update mutable fields
            changed = False
            for fld in ("ttl", "mx_pref", "is_frozen", "value", "host", "record_type"):
                # host/record_type/value won't differ given key match, but keep consistent
                newv = r.get(fld, None)
                if fld in ("host", "record_type", "value"):
                    newv = r[fld]
                if existing.get(fld) != newv:
                    existing[fld] = newv
                    changed = True
            if existing.get("status") != "active":
                existing["status"] = "active"
                changed = True
            if changed:
                existing["updated_at"] = now
                # also treat as synced now
                existing["last_synced_at"] = now
                updated_count += 1
            else:
                # Still mark last_synced_at to now as this is authoritative replace
                existing["last_synced_at"] = now
                existing["updated_at"] = now
                updated_count += 1
            # write back
            for i, rr in enumerate(dns_hosts):
                if isinstance(rr, dict) and rr.get("dns_host_id") == existing.get("dns_host_id"):
                    dns_hosts[i] = existing
                    break
        else:
            # Ensure no active uniqueness conflict exists (should not, since key absent in existing_active)
            # But check against current dns_hosts active set in case duplicates existed in store
            for rr in dns_hosts:
                if isinstance(rr, dict) and rr.get("domain_id") == domain_id and rr.get("status") == "active":
                    if _k(rr) == rk:
                        _log("error", "CONFLICT")
                        return _err("CONFLICT", "Active DNS record uniqueness constraint violated by existing data.", key={"host": r["host"], "record_type": r["record_type"], "value": r["value"], "mx_pref": r["mx_pref"]})

            dns_host_id = "nc_dh_" + os.urandom(12).hex()
            new_row = {
                "dns_host_id": dns_host_id,
                "domain_id": domain_id,
                "status": "active",
                "host": r["host"],
                "record_type": r["record_type"],
                "value": r["value"],
                "ttl": r.get("ttl", None),
                "mx_pref": r.get("mx_pref", None),
                "is_frozen": r.get("is_frozen", False),
                "last_synced_at": now,
                "created_at": now,
                "updated_at": now,
            }
            dns_hosts.append(new_row)
            inserted_count += 1

    if deleted_count == 0 and updated_count == 0 and inserted_count == 0:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No DNS host changes were applied.", domain_id=domain_id)

    _save("dns_hosts.json", dns_hosts)

    # Return active set after operation
    active_after = [
        r for r in dns_hosts
        if isinstance(r, dict) and r.get("domain_id") == domain_id and r.get("status") == "active"
    ]

    _log("ok", None)
    return {
        "domain_id": domain_id,
        "counts": {
            "inserted": inserted_count,
            "updated": updated_count,
            "deleted": deleted_count
        },
        "hosts": active_after
    }
